local function pyright_cmd()
  if vim.fn.executable('pyright-langserver') == 1 then
    return { 'pyright-langserver', '--stdio' }
  end

  -- GUI Neovim often skips shell rc, so nvm bin may be missing from PATH
  local matches = vim.fn.glob(vim.env.HOME .. '/.nvm/versions/node/*/bin/pyright-langserver', true, true)
  table.sort(matches)
  local bin = matches[#matches]
  if bin and bin ~= '' then
    return { bin, '--stdio' }
  end

  return { 'pyright-langserver', '--stdio' }
end

vim.lsp.config('pyright', {
  cmd = pyright_cmd(),
})
vim.lsp.config('clangd', {
  filetypes = { 'c', 'cpp', 'objc', 'objcpp', 'cuda' },
})
vim.lsp.enable('pyright')
vim.lsp.enable('clangd')

